    /// <summary>The class of a code point.</summary>
    /// <param name="codePoint">The code point.</param>
    /// <returns>Its class.</returns>
    public static BidiClass Of(int codePoint) {
        var low = 0;
        var high = Starts.Length - 1;

        while (low <= high) {
            var middle = (low + high) >> 1;

            if (codePoint < Starts[middle]) {
                high = middle - 1;
            } else if (codePoint > Ends[middle]) {
                low = middle + 1;
            } else {
                return Classes[middle];
            }
        }

        return BidiClass.Other;
    }
